#include "InputAlignment.h"
static void testInputAlignment(const File& root,Assets& assets){
    InputAlignmentSettings defaults;int64_t value=99;expect(resolveInputAlignment(defaults,48000,512,1024,value).wasOk()&&value==0,"alignment defaults Off without changing historical recordings");
    for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int mode=0;mode<4;++mode){InputAlignmentSettings settings{mode,12.5};int64_t frames=0;auto valid=resolveInputAlignment(settings,rate,137,251,frames);int64_t expected=mode==0?0:(int64_t)std::llround(rate*.0125)+(mode>=2?137:0)+(mode==3?251:0);expect(valid.wasOk()&&frames==expected,"reported input and output latencies resolve once in integer device samples");}
    InputAlignmentSettings kept{1,17},parsed=kept;auto json=inputAlignmentToJson(kept);expect(inputAlignmentFromJson(json,parsed).wasOk()&&parsed==kept,"local alignment preferences roundtrip independently of the project schema");
    for(auto field:{"schema","mode","manualMs"}){auto bad=JSON::parse(JSON::toString(json));bad.getDynamicObject()->removeProperty(field);expect(inputAlignmentFromJson(bad,parsed).failed()&&parsed==kept,"missing alignment preference fields reject without partial output");}
    for(auto wrong:{var(true),var("12"),var(),var(std::numeric_limits<double>::infinity())}){auto bad=JSON::parse(JSON::toString(json));bad.getDynamicObject()->setProperty("manualMs",wrong);expect(inputAlignmentFromJson(bad,parsed).failed()&&parsed==kept,"manual correction uses strict finite numeric bounds");}
    for(InputAlignmentSettings invalid:std::initializer_list<InputAlignmentSettings>{{-1,0},{4,0},{1,1000.1},{1,-1000.1},{1,std::numeric_limits<double>::quiet_NaN()}})expect(validateInputAlignment(invalid).failed(),"invalid correction modes and ranges reject before arming");
    value=71;expect(resolveInputAlignment({3,1000},48000,48001,0,value).failed()&&value==71&&resolveInputAlignment({2,0},48000,-1,0,value).failed(),"unavailable reports and excessive combined correction leave the output unchanged");expect(resolveInputAlignment({0,1000},48000,-1,-1,value).wasOk()&&value==0,"Off ignores stored manual correction and unavailable latency reports");
    for(double rate:{8000.,44100.,48000.,96000.})for(double bpm:{30.,120.,300.})for(int offset:{-1200,0,1200}){AlignedInputWindow w;auto valid=alignInputWindow(1,4,8,bpm,rate,offset,w);double fpb=60*rate/bpm;expect(valid.wasOk()&&std::abs(w.clipBeat-4)<1e-10&&std::abs(w.gateBeat-(4+offset/fpb))<1e-10&&w.frames==(uint64_t)std::floor(4*fpb+1e-7),"scheduled punch preserves intended placement and exact length across tempos rates and signed corrections");expect(w.startBeat<=w.gateBeat&&w.endBeat<=4096&&std::abs(w.endBeat-w.gateBeat-w.frames/fpb)<1e-10,"aligned capture remains inside bounded transport limits");}
    AlignedInputWindow w;expect(alignInputWindow(0,0,4,120,48000,-4800,w).wasOk()&&std::abs(w.clipBeat-.2)<1e-10&&w.frames==91200&&w.limited,"negative correction at Song start preserves the missing initial gap instead of inventing input");expect(alignInputWindow(4094,4094,4096,120,48000,4800,w).wasOk()&&std::abs(w.clipBeat-4094)<1e-8&&w.frames==43200&&w.limited,"positive correction near the timeline end shortens the capture safely");AlignedInputWindow before=w;expect(alignInputWindow(4096,4096,4096,120,48000,0,w).failed()&&w.frames==before.frames,"invalid or empty ranges reject without replacing a prepared window");
    // Drive the real sample-accurate gate and disk recorder with timestamped
    // synthetic dry input. Different callback partitions must collect the same PCM.
    auto p=emptyProject();p.bpm=120;p.songMode=true;p.loop=false;auto projectToken=JSON::toString(projectToJson(p));
    auto capture=[&](int offset,int block,const File& file,TakeCheckpoint* checkpoint=nullptr){AlignedInputWindow plan;bool ok=alignInputWindow(0,1,2,120,48000,offset,plan).wasOk();auto engine=makeEngine(p,assets,root);ok&=engine->beginTake({plan.startBeat,plan.gateBeat,plan.endBeat,4});Recorder recorder;ok&=recorder.start(file,48000,2,(plan.frames+.25)/48000,checkpoint).wasOk();AudioBuffer<float> audio(2,block),input(2,block);int64_t clock=0;for(int n=0;n<400000&&!engine->takeFinished.load();n+=block){for(int i=0;i<block;++i){float sample=(float)((clock+i)%10000)/20000;input.setSample(0,i,sample);input.setSample(1,i,-sample);}engine->render(audio.getWritePointer(0),audio.getWritePointer(1),block);if(engine->captureCount)recorder.capture(input.getReadPointer(0,engine->captureOffset),input.getReadPointer(1,engine->captureOffset),engine->captureCount);clock+=block;Thread::sleep(1);}ok&=recorder.finish().wasOk()&&recorder.frames()==plan.frames;expect(ok,"count-in and shifted punch collect the exact stereo frame budget through the disk recorder");return plan;};
    for(int offset:{-1200,0,1200}){auto a=root.getChildFile("alignment-"+String(offset)+"-127.wav"),b=root.getChildFile("alignment-"+String(offset)+"-511.wav");auto plan=capture(offset,127,a);capture(offset,511,b);AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> ar(fm.createReaderFor(a)),br(fm.createReaderFor(b));AudioBuffer<float> aa(2,24000),bb(2,24000);bool same=ar&&br&&ar->lengthInSamples==24000&&br->lengthInSamples==24000;if(same){ar->read(&aa,0,24000,0,true,true);br->read(&bb,0,24000,0,true,true);same=aa==bb;double expected=((96000+24000+offset)%10000)/20000.;same&=std::abs(aa.getSample(0,0)-expected)<2e-7&&std::abs(aa.getSample(1,0)+expected)<2e-7;}expect(same,"signed alignment captures the expected sample after count-in identically across callback sizes");}
    // Existing recovery metadata holds the final musical beat. No preference is
    // re-applied when recovering the verified PCM prefix.
    alignInputWindow(0,0,1,120,48000,-4800,w);TakeCheckpoint checkpoint;auto recordings=root.getChildFile("data/Recordings");expect(prepareTakeCheckpoint(p,root,recordings,7,w.clipBeat,48000,2,w.frames,checkpoint).wasOk(),"aligned recovery checkpoint stores the final musical position before capture");Recorder recorder;bool started=recorder.start(checkpoint.audio(),48000,2,(w.frames+.25)/48000,&checkpoint).wasOk();AudioBuffer<float> input(2,1024);for(int ch=0;ch<2;++ch)for(int i=0;i<1024;++i)input.setSample(ch,i,ch?.1f:-.1f);if(started)recorder.capture(input.getReadPointer(0),input.getReadPointer(1),1024);expect(started&&recorder.finish().wasOk(),"aligned interrupted-take fixture commits a verified dry PCM prefix");TakeCheckpoint latest;File recovered;Project restored;expect(readTakeCheckpoint(checkpoint.directory,latest).wasOk()&&recoverTakeCheckpoint(latest,recovered).wasOk()&&loadProject(recovered,restored).wasOk()&&std::abs(restored.clips.back().beat-.2)<1e-10&&std::abs(restored.clips.back().length-1024./48000*2)<1e-10,"interrupted recovery restores aligned placement once without any current driver or preference dependency");expect(JSON::toString(projectToJson(p))==projectToken,"alignment and recovery leave the source session intact");
}
